function commitAsOriginMain(dir) { git(dir, "add", "-A"); git(dir, "-c", "user.name=fixture", "-c", "user.email=fixture@invalid", "commit", "-q", "-m", "recipe"); git(dir, "update-ref", "refs/remotes/origin/main", "HEAD"); }
function writeRecipe(dir, fields) { mkdirSync(join(dir, ".fleet"), { recursive: true }); const recipe = { check: true, installClean: true, testCount: 1, uncovered: [], ...fields, derivedAt: git(dir, "rev-parse", "origin/main") }; writeFileSync(join(dir, ".fleet", "recipe.json"), `${JSON.stringify(recipe)}\n`); }
